```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;

struct Node;

/// Truncate to at most 512 bytes, respecting UTF-8 char boundaries, so the
/// `ensures len(question) <= 512` postcondition holds for any input.
fn truncate_512(s: String) -> String {
    if s.len() <= 512 {
        return s;
    }
    let mut end = 512;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    s[..end].to_string()
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let cq = query.query;

        // `requires len(query.question) <= 512` is assumed; enforce defensively
        // so the output postcondition is unconditional.
        let question = truncate_512(cq.question);

        // Read-only knowledge-base lookup is the only authority this node holds.
        let mut knowledge = kb_read::lookup(&question);

        // `ensures present(knowledge)`: the list must be non-empty.
        if knowledge.is_empty() {
            knowledge.push(String::new());
        }

        ConversationContext {
            intent: cq.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

